mapper.select:
select sd.D_Name as dName,sd.D_Code as dCode,sd.D_ID as dId,sp.P_Name as pName,sp.P_Id as pId,spu.U_Id as uId,spu.Pu_Main_Dep as puMainDep from SYS_Department sd left join SYS_Position sp on sd.D_ID=sp.D_ID left join SYS_Position_User spu on spu.P_ID=sp.P_ID where 1=1
and spu.U_ID in
#{uId}
and sd.Te_Id = #{teId}

        select pp.P_Id as pId,sd.D_Name as dName,sd.D_Code as dCode,sd.D_ID as dId from SYS_Department sd left join
        Pre_Project pp on sd.D_ID=pp.P_Competent_Department
        where 1=1

        
            and pp.P_Id in
            
                #{pId}
            
        
        
            and sd.Te_Id = #{params.teId}

        select t1.dName,t1.Tpt_D_Id as dId,t1.Tpt_User as userId,t1.Tpt_User_Name as
        uName,t1.Tpt_User_Account as userAccount,count(tp_id) as
        tpCount,sum(rejectCount)as
        rejectCount,sum(overtime) as overtimeCount,sum(Tpt_Duration) as handlingTime from (
        select *,case when Tpt_Approval_Type='退回' then 1 else 0 end as rejectCount,case when (Tpt_Timeout_Time is null
        or Tpt_Timeout_Time=0) then 0 else (case when Tpt_Duration>Tpt_Timeout_Time then 1 else 0 end) end as overtime,
        case when Tpt_D_Name is null or Tpt_D_Name='' then Tpt_P_Dname else Tpt_D_Name end as dName
        from Sys_Task_Processin_Time
        where
        Tpt_Act_Type not like '%Gateway' and
        Tpt_Act_Id not like 'Gateway_%' and

        Tpt_Begin_Time is not null
        
            and Te_Id = #{params.teId}
        
        
            and Tpt_Approval_Type in
            
                #{tpType}
            
        

        
            and Tpt_Act_Name not in
            
                #{actName}
            
        
        
            and Tpt_User not in
            
                #{uId}
            
        
        
            and Tpt_Act_Name not in
            
                #{actName}
            
        
        
            and
             >= #{params.starTime}
        
        
            and<= #{params.endTime}
        
        
            and
             >= #{params.completeStarTime}
            and<= #{params.completeEndTime}
            and Tpt_Approval_State=7
        
        
            and Tpt_User_Account=#{params.userAccount}
        
        
            and Tpt_User_Name like concat('%',#{params.uName},'%')
        
        
            and Tpt_File_Code like concat('%',#{params.tptFileCode},'%')
        
        
            and Tpt_User_Type=#{params.uType}
        

        
            and Tpt_D_Id in
            
                #{dId}
            
        
        )t1 group by t1.dName,t1.Tpt_User_Account,t1.Tpt_D_Id,t1.Tpt_User,t1.Tpt_User_Name
        
            
                order by ${params.sortFiled} ${params.sortType}
            
            
                order by ${params.sortSideFiled} ${params.sortType}
            
            
                order by dName DESC
            
        
        limit #{params.start},#{params.size}

        select count(1) from ( select t1.dName as dName from (
        select *,case when Tpt_Approval_Type='退回' then 1 else 0 end as rejectCount,case when (Tpt_Timeout_Time is null
        or Tpt_Timeout_Time=0) then 0 else (case when Tpt_Duration>Tpt_Timeout_Time then 1 else 0 end) end as overtime,
        case when Tpt_D_Name is null or Tpt_D_Name='' then Tpt_P_Dname else Tpt_D_Name end as dName
        from Sys_Task_Processin_Time
        where
        Tpt_Act_Type not like '%Gateway' and
        Tpt_Act_Id not like 'Gateway_%' and
        Tpt_Begin_Time is not null
        
            and Te_Id = #{params.teId}
        
        
            and Tpt_Approval_Type in
            
                #{tpType}
            
        
        
            and Tpt_User not in
            
                #{uId}
            
        
        
            and Tpt_Act_Name not in
            
                #{actName}
            
        
        
            and
             >= #{params.starTime}
        
        
            and<= #{params.endTime}
        
        
            and
             >= #{params.completeStarTime}
            and<= #{params.completeEndTime}
            and Tpt_Approval_State=7
        
        
            and Tpt_User_Account=#{params.userAccount}
        
        
            and Tpt_User_Name like concat('%',#{params.uName},'%')
        
        
            and Tpt_File_Code like concat('%',#{params.tptFileCode},'%')
        
        
            and Tpt_User_Type=#{params.uType}
        

        
            and Tpt_D_Id in
            
                #{dId}
            
        
        )t1 group by t1.dName,t1.Tpt_User_Account,t1.Tpt_D_Id,t1.Tpt_User,t1.Tpt_User_Name)a1

        select * from Sys_Task_Processin_Time
        where
        Tpt_Act_Type not like '%Gateway' and
        Tpt_Act_Id not like 'Gateway_%' and
        Tpt_Begin_Time is not null
        
            and Te_Id = #{params.teId}
        
        
            and Tpt_Approval_Type in
            
                #{tpType}
            
        
        
