            and Tpt_D_Id in
            
                #{dId}
            

        
        )t1 group by t1.dName,t1.dId
        )a1

        select Tpt_D_Id,Tpt_D_Name as dName,
        count(tp_id) as completionNode,
        sum( case when Tpt_Approval_Type='退回' then 1 else 0 end) as rejectNode,
        count(DISTINCT case when Tpt_Approval_State='7' then Tpt_File_Id else null end) as completionFile ,
        count(DISTINCT case when Tpt_Approval_State='7' and Tpt_Approval_Type='退回' then Tpt_File_Id else null end) as
        rejectFile from (select * from sys_task_processin_time
        where
        Tpt_Act_Type not like '%Gateway' and
        Tpt_Act_Id not like 'Gateway_%'
        
            and Te_Id = #{params.teId}
        
        
            and Tpt_Approval_Type in
            
                #{tpType}
            
        
        
            and Tpt_User not in
            
                #{uId}
            
        
        
            and Tpt_Act_Name not in
            
                #{actName}
            
        
        
            and Tpt_File_Code like concat('%',#{params.tptFileCode},'%')
        
        
            and
             >= #{params.starTime}
        
        
            and<= #{params.endTime}
        
        
            and
             >= #{params.completeStarTime}
            and<= #{params.completeEndTime}
            and Tpt_Approval_State=7
        
        
            and Tpt_User_Account=#{params.userAccount}
        
        
            and Tpt_User_Name like concat('%',#{params.uName},'%')
        
        
            and Tpt_User_Type=#{params.uType}
        

        
            and Tpt_D_Id in
            
                #{dId}
            

        

        ) t1 group by Tpt_D_Id,Tpt_D_Name

        
            
                order by ${params.sortFiled} ${params.sortType}
            
            
                order by ${params.sortSideFiled} ${params.sortType}
            
            
                order by Tpt_D_Name DESC
            
        
        limit #{params.start},#{params.size}

        select count(1) from ( select Tpt_D_Id,Tpt_D_Name as dName,
        count(tp_id) as completionNode,
        sum( case when Tpt_Approval_Type='退回' then 1 else 0 end) as rejectNode,
        count(DISTINCT case when Tpt_Approval_State='7' then Tpt_File_Id else null end) as completionFile ,
        count(DISTINCT case when Tpt_Approval_State='7' and Tpt_Approval_Type='退回' then Tpt_File_Id else null end) as
        rejectFile from (select * from sys_task_processin_time
        where
        Tpt_Act_Type not like '%Gateway' and
        Tpt_Act_Id not like 'Gateway_%'
        
            and Te_Id = #{params.teId}
        
        
            and Tpt_Approval_Type in
            
                #{tpType}
            
        
        
            and Tpt_User not in
            
                #{uId}
            
        
        
            and Tpt_Act_Name not in
            
                #{actName}
            
        
        
            and Tpt_File_Code like concat('%',#{params.tptFileCode},'%')
        
        
            and
             >= #{params.starTime}
        
        
