        count(DISTINCT case when Tpt_Approval_State=7 and Tpt_Approval_Type='退回' then Tpt_File_Id else null end) as
        rejectFile from (select * from sys_task_processin_time where
        Tpt_Act_Type not like '%Gateway' and
        Tpt_Act_Id not like 'Gateway_%'
        
            and Te_Id = #{params.teId}
        
        
