        select D_Id as did,D_Name as dname,Tpt_User_Name as uname,Tpt_User_Account as uaccount,P_Name as pname,Tpt_Name
        as filetitle,Tpt_File_Code as filecode,Tpt_File_Id as tptFileId,Tpt_Act_Name as actname,count(tp_id) as rejectionsnumber,
        
        from (
        select
        case when Tpt_D_Id is null or Tpt_D_Id='' then Tpt_P_Did else Tpt_D_Id end as D_Id,
        case when Tpt_D_Name is null or Tpt_D_Name='' then Tpt_P_Dname else Tpt_D_Name end as D_Name,
        Tpt_User_Name,Tpt_User_Account,P_Name,Tpt_File_Code,Tpt_File_Id,Tpt_Name,Tpt_Act_Name,tp_id,Tpt_Explain
        from Sys_Task_Processin_Time tpt
        left join Pre_Project pp on tpt.Tpt_P_Id=pp.P_ID
        where
        Tpt_Act_Type not like '%Gateway' and
        Tpt_Act_Id not like 'Gateway_%' and
