        )d1

        select D_Id as did,D_Name as dname,Tptr_User_Name as uname,Tptr_User_Account as uaccount,P_Name as
        pname,Tpt_Name as filetitle,Tpt_File_Code as filecode,Tpt_File_Id as TptFileId, Tptr_Act_Name as actname,count(tp_id) as rejectionsnumber,
        
