            and Tptr_D_Id in
            
                #{dId}
            

        
        )t1 group by D_Id,D_Name,Tptr_User_Name,Tptr_User_Account,P_Name,Tpt_File_Code,Tpt_File_Id,Tpt_Name,Tptr_Act_Name

        
            
                order by ${params.sortFiled} ${params.sortType}
            
            
                order by ${params.sortSideFiled} ${params.sortType}
            
            
                order by D_Name DESC
            
        
        limit #{params.start},#{params.size}

        select count(1) from (
        select D_Id as did,D_Name as dname,Tptr_User_Name as uname,Tptr_User_Account as uaccount,P_Name as
        pname,Tpt_Name
        as filetitle,Tpt_File_Code as filecode,Tpt_File_Id AS tptFileId,Tptr_Act_Name as actname,count(tp_id) as rejectionsnumber,
        
        from (
        select
        case when Tptr_D_Id is null or Tptr_D_Id='' then Tpt_P_Did else Tptr_D_Id end as D_Id,
        case when Tptr_D_Name is null or Tptr_D_Name='' then Tpt_P_Dname else Tptr_D_Name end as D_Name,
        Tptr_User_Name,Tptr_User_Account,P_Name,Tpt_File_Code,Tpt_File_Id,Tpt_Name,Tptr_Act_Name,tp_id,Tpt_Explain
        from Sys_Task_Processin_Time tpt
        left join Pre_Project pp on tpt.Tpt_P_Id=pp.P_ID
        where
        Tpt_Act_Type not like '%Gateway' and
        Tpt_Act_Id not like 'Gateway_%' and
        Tpt_Approval_Type='退回'
        
            and Te_Id = #{params.teId}
        
        
            and Tpt_Approval_Type in
            
                #{tpType}
            
        
        
            and Tptr_User_Id not in
            
                #{uId}
            
        
        
            and Tpt_Act_Name not in
            
                #{actName}
            
        
        
            and Tpt_File_Code like concat('%',#{params.tptFileCode},'%')
        
        
            and
             >= #{params.starTime}
        
        
            and<= #{params.endTime}
        
        
            and
             >= #{params.completeStarTime}
            and<= #{params.completeEndTime}
            and Tpt_Approval_State=7
        
        
            and Tptr_User_Account=#{params.userAccount}
        
        
            and Tptr_User_Name like concat('%',#{params.uName},'%')
        
        
            and Tptr_User_Type=#{params.uType}
        

        
            and Tptr_D_Id in
            
                #{dId}
            
        
        )t1 group by D_Id,D_Name,Tptr_User_Name,Tptr_User_Account,P_Name,Tpt_File_Code,Tpt_File_Id,Tpt_Name,Tptr_Act_Name
        )d1

        select sdp.D_Id,sdp.D_Name,sdp.D_Code from SYS_File sf
        left join Pre_Project prp on sf.FileProject=prp.P_ID
        left join SYS_Department sdp on sdp.D_ID=prp.P_Competent_Department
        where sf.FileID=#{fileId}
        
            and Te_Id = #{teId}
        
        limit 0,1

select tp_id from Sys_Task_Processin_Time where
Tpt_File_Id in

    #{fileId}


    and Te_Id = #{teId}

        select * from Sys_Task_Processin_Time where Tpt_File_Code is  null and  Tpt_File_Id is not null  
        and Te_Id = #{teId}
     and ((
             >= #{starTime}
            and < #{endTime}
        ) or (
             >= #{starTime}
            and < #{endTime}
        ))
